#include <Arduino.h>

unsigned long lastReport = 0;

void setup() {
  pinMode(A0, INPUT);
  pinMode(2, INPUT_PULLUP);
  Serial.begin(9600);
  lastReport = millis();
}

void loop() {
  unsigned long now = millis();
  if ((unsigned long)(now - lastReport) >= 1000UL) {
    lastReport += 1000UL;
    int potentiometer = analogRead(A0);
    int buttonLevel = digitalRead(2);
    Serial.print("A0=");
    Serial.print(potentiometer);
    Serial.print(" D2=");
    Serial.println(buttonLevel);
  }
}
